package com.petcare.backend.controller;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
import com.petcare.backend.dto.blog.response.*;import com.petcare.backend.dto.common.PageResponse;import com.petcare.backend.model.Blog;import com.petcare.backend.security.UserPrincipal;import com.petcare.backend.service.BlogService;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.domain.PageImpl;import org.springframework.http.HttpStatus;
@ExtendWith(MockitoExtension.class) class BlogControllerTest {@Mock BlogService service;@Mock UserPrincipal principal;BlogController controller;@BeforeEach void init(){controller=new BlogController(service);}@Test void allEndpointsDelegate(){PageResponse<BlogResponse> page=PageResponse.from(new PageImpl<>(List.of()));BlogResponse response=BlogResponse.builder().id(1L).build();when(service.getBlogCategories()).thenReturn(List.of());when(service.getPublishedBlogs(principal,"x",Blog.BlogCategory.health,0,10)).thenReturn(page);when(service.getSavedBlogs(principal,0,10)).thenReturn(page);when(service.getPublishedBlogDetail(principal,1L)).thenReturn(response);when(service.saveBlog(principal,1L)).thenReturn(response);assertThat(controller.getBlogCategories().getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(controller.getPublishedBlogs(principal,"x",Blog.BlogCategory.health,0,10).getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(controller.getSavedBlogs(principal,0,10).getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(controller.getBlogDetail(principal,1L).getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(controller.saveBlog(principal,1L).getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(controller.unsaveBlog(principal,1L).getStatusCode()).isEqualTo(HttpStatus.OK);verify(service).unsaveBlog(principal,1L);}}
